import argparse
import json
import re
import shutil
from pathlib import Path

import jinja2
import yaml

# First line of every generated file, used to know which folders can be removed
GENERATED_MARK = "Generated by utils_biobb nextflow_generator.py from the JSON schemas: do not edit by hand."
NEXTFLOW_VERSION = ">=25.04.0"
# Properties managed by the adapter or by Nextflow, not shown in the README
HIDDEN_PROPERTIES = {"restart", "container_path", "container_image", "container_volume_path",
                     "container_working_dir", "container_user_id", "container_shell_path"}
# Default properties of every block (Groovy values): Nextflow already keeps the console log in .command.log
DEFAULT_PROPERTIES = {"can_write_file_log": "false"}
# Properties set from the task resources when the block has them: {property: (Groovy value, label)}
RESOURCE_PROPERTIES = {"num_threads": ("task.cpus", "process_medium")}


class NextflowGenerator():

    def __init__(self, package, input_path, output_path, namespace="bioexcel", **kwargs):

        self.package = package

        # check if input_path exists
        if not Path(input_path).exists():
            raise SystemExit('Unexisting input path')

        self.input_path = Path(input_path)
        self.output_path = Path(output_path)
        self.output_path.mkdir(parents=True, exist_ok=True)
        self.namespace = namespace

        template_env = jinja2.Environment(loader=jinja2.FileSystemLoader(str(Path(__file__).parent.joinpath("templates"))),
                                          keep_trailing_newline=True)
        self.main_template = template_env.get_template("main.nf.j2")
        self.readme_template = template_env.get_template("README.md.j2")

    def getExtensions(self, file_formats):
        """ returns the extensions of the accepted formats ('directory' for folders) """

        extensions = []
        for frmt in file_formats:
            gr = re.match(r'^\.\*\\\.([A-Za-z0-9_.]+)\$$', frmt['extension'])
            if not gr:
                raise SystemExit(f"Unsupported extension pattern: {frmt['extension']}")
            extensions.append(gr.groups()[0])

        return extensions

    def getRole(self, argument):
        """ returns the output file role: output argument without output_ prefix and _path suffix """

        return re.sub(r'_path$', '', re.sub(r'^output_', '', argument))

    def getPattern(self, extensions):
        """ returns the glob pattern of an input argument """

        alternatives = ["*" if ext == "directory" else "*." + ext for ext in extensions]
        return alternatives[0] if len(alternatives) == 1 else "{" + ",".join(alternatives) + "}"

    def groovyValue(self, value):
        """ returns a Groovy literal of a JSON value """

        if isinstance(value, bool):
            return str(value).lower()
        if value is None:
            return "null"
        if isinstance(value, (int, float)):
            return str(value)
        if isinstance(value, list):
            return "[" + ", ".join(self.groovyValue(v) for v in value) + "]"
        if isinstance(value, dict):
            return self.groovyMap({k: self.groovyValue(v) for k, v in value.items()})
        return "'" + str(value).replace("\\", "\\\\").replace("'", "\\'") + "'"

    def groovyMap(self, items):
        """ returns a Groovy map literal of already formatted values """

        if not items:
            return "[:]"
        return "[" + ", ".join(f"{k if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', k) else repr(k)}: {v}" for k, v in items.items()) + "]"

    def tableText(self, text):
        """ returns a text that fits in a Markdown table cell """

        return " ".join(str(text).split()).replace("|", "\\|")

    def getArguments(self, tool_schema):
        """ returns input and output arguments: required first, then optional, in schema order """

        inputs, outputs = [], []
        for attr, value in tool_schema['properties'].items():
            if attr == 'properties':
                continue
            arg = {
                "name": attr,
                "optional": attr not in tool_schema['required'],
                "type": value['type'],
                "description": value['description'],
                "formats": self.getExtensions(value['file_formats']),
                "edam": ["http://edamontology.org/" + frmt['edam'] for frmt in value['file_formats'] if frmt.get('edam')],
                "sample": value.get('sample')
            }
            if value['filetype'] == 'input':
                inputs.append(arg)
            else:
                arg["role"] = self.getRole(attr)
                alternatives = ["" if ext == "directory" else "." + ext for ext in arg["formats"]]
                arg["glob"] = "*." + arg["role"] + (alternatives[0] if len(alternatives) == 1 else "{" + ",".join(alternatives) + "}")
                outputs.append(arg)

        def sort_key(arg):
            return arg["optional"]

        return sorted(inputs, key=sort_key), sorted(outputs, key=sort_key)

    def getProperties(self, tool_schema):
        """ returns the documented properties of the block """

        properties = []
        for name, value in tool_schema['properties'].get('properties', {}).get('properties', {}).items():
            if name in HIDDEN_PROPERTIES:
                continue
            description = value.get('description', '')
            if value.get('enum'):
                description += " Values: " + ", ".join(str(v) for v in value['enum']) + "."
            properties.append({
                "name": name,
                "type": value.get('type', ''),
                "default": self.tableText(json.dumps(value.get('default'))),
                "description": self.tableText(description)
            })

        return properties

    def getOutputNames(self, outputs):
        """ returns the Groovy definitions of the output file names: <prefix>.<role>.<extension>, '' if not requested """

        lines = []
        for arg in outputs:
            name, role = arg["name"], arg["role"]
            file_name = f"\"${{prefix}}.{role}.${{outputs.{name}}}\""
            if arg["type"] == "dir":
                file_name = f"(outputs.{name} == 'directory' ? \"${{prefix}}.{role}\" : {file_name})"
            lines.append(f"def {name} = outputs.{name} ? {file_name} : ''")

        return lines

    def getCommand(self, basename, inputs, outputs):
        """ returns the block command line, one argument per line """

        lines = [f"{basename} --config config.json"]
        for arg in inputs + outputs:
            name = arg["name"]
            if arg["optional"]:
                lines.append(f"${{{name} ? \"--{name} ${{{name}}}\" : ''}}")
            else:
                lines.append(f"--{name} ${{{name}}}")

        return " \\\\\n        ".join(lines)

    def getStub(self, outputs):
        """ returns the stub commands creating every requested output """

        stub = []
        for arg in outputs:
            name = arg["name"]
            create = "touch"
            if arg["type"] == "dir":
                create = f"${{outputs.{name} == 'directory' ? 'mkdir -p' : 'touch'}}"
            command = f"{create} ${{{name}}}"
            if arg["optional"]:
                command = f"${{{name} ? \"{command}\" : ''}}"
            stub.append(command)

        return stub

    def getMeta(self, context, inputs, outputs):
        """ returns the meta.yml spec of the module (https://github.com/nextflow-io/schemas module schema) """

        def meta():
            return {"name": "meta", "type": "map", "description": "Map with at least an id key, used as tag and output file prefix"}

        def channel(arg):
            return {
                "name": arg["name"],
                "type": "directory" if arg["type"] == "dir" else "file",
                "description": " ".join(arg["description"].split()),
                "pattern": arg["glob"] if "glob" in arg else self.getPattern(arg["formats"]),
                "optional": arg["optional"],
                "ontologies": [{"edam": edam} for edam in dict.fromkeys(arg["edam"])]
            }

        def versions():
            return [{"name": "process", "type": "string", "description": "Name of the process"},
                    {"name": "package", "type": "string", "description": "Name of the biobb package"},
                    {"name": "version", "type": "string", "description": "Version of the biobb package"}]

        return {
            "$schema": "https://raw.githubusercontent.com/nextflow-io/schemas/refs/heads/main/module/v1/schema.json",
            "name": context["module_name"],
            "version": context["version"],
            "kind": "Process",
            "description": context["title"],
            "keywords": list(dict.fromkeys(context["keywords"])),
            "license": "Apache-2.0",
            "requires": {"nextflow": NEXTFLOW_VERSION},
            "tools": [{self.package: {
                "description": context["package_description"],
                "homepage": context["github"],
                "documentation": context["docs"],
                "licence": ["Apache-2.0"]
            }}],
            "input": [[meta()] + [channel(arg) for arg in inputs]] if inputs else [meta()],
            "output": [[meta(), channel(arg)] for arg in outputs] + [versions()],
            "topics": [versions()]
        }

    def generateModule(self, tool_schema, pckg_schema, basename):
        """ generates the main.nf, meta.yml and README.md of a block """

        tools = [item for item in pckg_schema['tools'] if item['exec'] == basename]
        assert len(tools) > 0, f"Tool {basename} not found in the package schema."
        tool = tools[0]

        inputs, outputs = self.getArguments(tool_schema)
        schema_properties = tool_schema['properties'].get('properties', {}).get('properties', {})

        label = "process_single"
        default_properties = dict(DEFAULT_PROPERTIES)
        for prop, (value, prop_label) in RESOURCE_PROPERTIES.items():
            if prop in schema_properties:
                default_properties[prop] = value
                label = prop_label

        # README example: first property with allowed values, else first one with a default
        candidates = {p: v for p, v in schema_properties.items() if p not in HIDDEN_PROPERTIES and p not in RESOURCE_PROPERTIES}
        example_properties = next((f"{p}: {self.groovyValue(v['enum'][0])}" for p, v in candidates.items() if v.get('enum')), None) or \
            next((f"{p}: {self.groovyValue(v['default'])}" for p, v in candidates.items() if v.get('default') not in (None, {}, [], "")), "")

        module = f"{self.package}_{basename}"
        context = {
            "mark": GENERATED_MARK,
            "module_name": f"{self.namespace}/{module}",
            "process_name": module.upper(),
            "package": self.package,
            "block": tool['block'],
            "version": pckg_schema['version'],
            "title": tool_schema['title'],
            "description": " ".join(tool_schema['description'].split()),
            "docs": tool['docs'],
            "github": pckg_schema['github'],
            "package_description": pckg_schema['desc'],
            "keywords": [self.package, basename] + pckg_schema.get('keywords', []),
            "docker": pckg_schema['docker'].replace("https://", ""),
            "singularity": pckg_schema['singularity'],
            "label": label,
            "inputs": [dict(arg, description=self.tableText(arg["description"])) for arg in inputs],
            "outputs": [dict(arg, description=self.tableText(arg["description"])) for arg in outputs],
            "default_outputs": self.groovyMap({arg["name"]: self.groovyValue(arg["formats"][0]) for arg in outputs}),
            "default_properties": self.groovyMap(default_properties),
            "example_properties": example_properties,
            "properties": self.getProperties(tool_schema),
            "output_names": self.getOutputNames(outputs),
            "command": self.getCommand(basename, inputs, outputs),
            "stub": self.getStub(outputs),
            "call_example": "ch_input" if inputs else "channel.of([id: 'sample'])"
        }

        module_path = self.output_path.joinpath(basename)
        module_path.mkdir(parents=True, exist_ok=True)

        with open(module_path.joinpath("main.nf"), "w") as main_file:
            main_file.write(self.main_template.render(**context))
        with open(module_path.joinpath("meta.yml"), "w") as meta_file:
            meta_file.write(f"# {GENERATED_MARK}\n")
            yaml.dump(self.getMeta(context, inputs, outputs), meta_file, sort_keys=False, width=1000, allow_unicode=True)
        with open(module_path.joinpath("README.md"), "w") as readme_file:
            readme_file.write(self.readme_template.render(**context))

    def removeOldModules(self):
        """ removes the generated modules, so there are no old/renamed biobbs """

        for main_path in self.output_path.glob("*/main.nf"):
            if GENERATED_MARK in main_path.read_text():
                shutil.rmtree(main_path.parent)

    def launch(self):
        """ launch function for NextflowGenerator """

        with open(self.input_path.joinpath(self.package + '.json')) as json_file:
            pckg_schema = json.load(json_file)

        self.removeOldModules()

        for json_file_path in sorted(self.input_path.glob("*.json")):
            if json_file_path.stem == self.package:
                continue
            with open(json_file_path) as json_file:
                tool_schema = json.load(json_file)

            self.generateModule(tool_schema, pckg_schema, json_file_path.stem)

            print(str(self.output_path.joinpath(json_file_path.stem)) + " module saved")


def main():
    parser = argparse.ArgumentParser(description="Creates Nextflow modules from given json schema.",
                                     formatter_class=lambda prog: argparse.RawTextHelpFormatter(prog, width=99999),
                                     epilog='Examples: \n'
                                            'nextflow_generator.py -p biobb_package -i path/to/json_schemas -o path/to/nextflow_adapters\n'
                                            'nextflow_generator.py --package biobb_package --input path/to/json_schemas --output path/to/nextflow_adapters')
    parser.add_argument('--namespace', '-n', default='bioexcel', help='Nextflow module registry namespace (default: bioexcel).')
    required_args = parser.add_argument_group('required arguments')
    required_args.add_argument('--package', '-p', required=True, help='BioBB package from where the json schemas will be taken.')
    required_args.add_argument('--input', '-i', required=True, help='Path to the folder from where the json schemas will be taken.')
    required_args.add_argument('--output', '-o', required=True, help='Output path to the Nextflow modules folder.')

    args = parser.parse_args()

    NextflowGenerator(package=args.package, input_path=args.input, output_path=args.output, namespace=args.namespace).launch()


if __name__ == '__main__':
    main()
